package common

import("bytes";"encoding/json";"fmt";"net/http")
type WhatsAppAdapter struct{Token,PhoneNumberID string;Client *http.Client}
func(a WhatsAppAdapter)ParseEvent(payload map[string]any)(InboundEvent,error){value:=payload;if entries,ok:=payload["entry"].([]any);ok&&len(entries)>0{entry,_:=entries[0].(map[string]any);changes,_:=entry["changes"].([]any);if len(changes)>0{change,_:=changes[0].(map[string]any);value,_=change["value"].(map[string]any)}};messages,_:=value["messages"].([]any);if len(messages)==0{return InboundEvent{},fmt.Errorf("WhatsApp webhook has no message")};message,_:=messages[0].(map[string]any);user,_:=message["from"].(string);if user==""{return InboundEvent{},fmt.Errorf("WhatsApp message has no sender")};raw,_:=message["type"].(string);kind:=raw;if raw=="document"{kind="file"};item,_:=message[raw].(map[string]any);if raw=="document"{item,_=message["document"].(map[string]any)};event:=InboundEvent{Platform:"whatsapp",UserID:user,ContentType:kind};event.Text,_=item["body"].(string);if event.Text==""{event.Text,_=item["caption"].(string)};event.MediaURL,_=item["id"].(string);return event,nil}
func(a WhatsAppAdapter)SendReply(event InboundEvent,reply OutboundReply)error{client:=a.Client;if client==nil{client=http.DefaultClient};for _,message:=range reply.Messages{kind:=message.Type;if kind=="file"{kind="document"};body:=map[string]any{"messaging_product":"whatsapp","to":event.UserID,"type":kind};if kind=="text"{body["text"]=map[string]string{"body":message.Text}}else{if message.MediaURL==""{return fmt.Errorf("WhatsApp media reply requires media ID")};body[kind]=map[string]any{"id":message.MediaURL}};data,_:=json.Marshal(body);req,_:=http.NewRequest(http.MethodPost,"https://graph.facebook.com/v20.0/"+a.PhoneNumberID+"/messages",bytes.NewReader(data));req.Header.Set("Authorization","Bearer "+a.Token);req.Header.Set("Content-Type","application/json");resp,err:=client.Do(req);if err!=nil{return err};resp.Body.Close();if resp.StatusCode/100!=2{return fmt.Errorf("WhatsApp API returned %s",resp.Status)}};return nil}
